if(halt){await keep(j);break;}
if(!j.revised_ink){j.ink_prompt=`Convert this exact ${j.id} corrected sheet to clean precise BLACK INK on WHITE. Preserve every panel, all full-body poses, the exact same identity, age, physique, face and hair, clothes, weapon geometry including true blade cross-section, all props, labels and notes. Preserve corrected full hands with every fingertip and visible white gap from left edge. Do not enlarge, crop or redesign. Remove colored/gray paint fills, use fine black contours and sparse controlled black hatching. Any cloth FACE MASK in the input MUST remain opaque cloth covering exactly the SAME nose and mouth areas in exactly the SAME body or expression views. Do NOT reveal lips, teeth, mouth or nose beneath cloth; express emotion using eyes and brows in masked views. Keep all original modern body views. Entire original 4:3 landscape canvas.`;
j.revised_ink=await generate({prompt:j.ink_prompt,referenced_image_paths:[j.revised_color],transparent_background:false});}
await keep(j);done++;notify({correction_published:j.id,done,total:jobs.length});
}catch(e){halt=true;notify({id:j.id,error:String(e),color:j.revised_color,ink:j.revised_ink});try{await keep(j);}catch(er){notify(String(er));}}}}
const all=Promise.all([worker(),worker(),worker()]);await yield_control();await all;await chain.catch(e=>notify(String(e)));text({done,halt,total:jobs.length});
